syntax:
// header: parameters (formal)
int add(int x, int y)
{
    return x + y;
}

int main()
{
    int a = 7, b = 5;
    int s = add(a, b);          // arguments (actual): a and b
    cout << add(100, 250);      // arguments can be plain values
    cout << add(a * 2, b + 1);  // ... or expressions
    int t = add(add(1, 2), 3);  // a returned value can be an argument
    return 0;
}

sample.code:
#include <iostream>
using namespace std;

int area(int length, int width) {
    return length * width;
}

int main() {
    int l = 8, w = 5;
    cout << "Area = " << area(l, w) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int subtract(int a, int b) {
    return a - b;
}

int main() {
    int x = 10, y = 3;
    cout << subtract(x, y) << endl;
    cout << subtract(y, x) << endl;
    cout << subtract(2 * 5, y + 1) << endl;
    cout << subtract(9.8, 2) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int square(int n) {
    return n * n;
}

int sumOfSquares(int a, int b) {
    return square(a) + square(b);
}

int main() {
    int a, b;
    cin >> a >> b;
    cout << "Sum of squares = " << sumOfSquares(a, b) << endl;
    cout << "Square of a + 1 = " << square(a + 1) << endl;
    return 0;
}

